INSERT INTO "platform_automation_rules" ("id", "name", "description", "trigger", "conditions", "actions", "enabled", "cooldown_minutes", "max_actions_per_run", "archived_at", "last_run_at", "last_result", "created_by", "created_at", "updated_by", "updated_at") VALUES ('99696f13-8966-4357-94d7-5b1067c896cc', 'Repeated integration failures → technical support', 'Tell technical support when a merchant''s integrations keep failing.', 'integration_failures', '{"hours":24,"min_errors":5}', '[{"type":"notify_staff","action":"edit","module":"integrations","severity":"WARN"},{"type":"notify_account_manager"}]', 1, 1440, 25, NULL, NULL, NULL, NULL, '2026-10-12T12:18:20.612Z', NULL, '2026-10-12T12:18:20.612Z');
